@Override // neth.iecal.curbox.services.BaseBlockingService, android.accessibilityservice.AccessibilityService
public void onAccessibilityEvent(AccessibilityEvent event) {
    if (event == null) {
        return;
    }
    super.onAccessibilityEvent(event);
    try {
        Boolean SUPPORTS_ANTI_UNINSTALL = BuildConfig.SUPPORTS_ANTI_UNINSTALL;
        Intrinsics.checkNotNullExpressionValue(SUPPORTS_ANTI_UNINSTALL, "SUPPORTS_ANTI_UNINSTALL");
        if (SUPPORTS_ANTI_UNINSTALL.booleanValue()) {
            this.antiUninstallBlocker.doAntiUninstallCheck(event);
        }
        this.appBlocker.doAppBlockerCheck(event);
        this.grayScaleFilter.doGrayscaleCheck(event);
        this.focusModeBlocker.doFocusModeCheck(event);
    } catch (Throwable th) {
        String message = th.getMessage();
        if (message == null) {
            message = "Unknown error";
        }
        Log.e("error", message);
        CrashLogger crashLogger = this.crashLogger;
        if (crashLogger == null) {
            Intrinsics.throwUninitializedPropertyAccessException("crashLogger");
            crashLogger = null;
        }
        crashLogger.logNonFatalError(new Exception(th));
    }
    try {
        this.appUsageTracker.onEvent(event);
        this.mindfulMessage.onEvent(event);
    } catch (Exception e) {
        Log.e("Usage Tracking error", e.toString());
    }
    AccessibilityEvent accessibilityEventObtain = AccessibilityEvent.obtain(event);
    Channel<AccessibilityEvent> channel = this.eventChannel;
    Intrinsics.checkNotNull(accessibilityEventObtain);
    if (ChannelResult.m1870isFailureimpl(channel.mo1846trySendJP2dKIU(accessibilityEventObtain))) {
        accessibilityEventObtain.recycle();
    }
}
